from math import gcd

def harmonic_cycle_length(k: int, n: int = 12) -> int:
    """Length of the harmonic cycle generated by an interval of k semitones
    in n-tone equal temperament: the additive order of k in Z/nZ.

    Complexity: O(log n) for the Euclidean gcd.
    """
    k %= n
    if k == 0:
        return 1
    return n // gcd(n, k)

